// ─── File: SettlementP2PDemo.java ───
// Peer-to-Peer: every Peer is both client and server; no central authority.
// Entries commit by majority consensus across peers.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SettlementP2PDemo {
    private static final Logger log = Logger.getLogger("P2P");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        P2PNetwork network = new P2PNetwork();
        Peer nbi = new Peer("National Bank of India", network);
        Peer hdfc = new Peer("HDFC", network);
        Peer icici = new Peer("ICICI", network);
        network.join(nbi); network.join(hdfc); network.join(icici);

        // NBI proposes a settlement entry — it acts as a CLIENT here.
        log.info("--- NBI proposes a settlement of 10,00,000 to HDFC ---");
        nbi.propose(new LedgerEntry("E1", "National Bank of India", "HDFC", new BigDecimal("1000000")));

        // One peer goes offline; the network still reaches majority and survives.
        log.info("--- ICICI goes offline; NBI proposes another entry ---");
        network.leave(icici);
        nbi.propose(new LedgerEntry("E2", "National Bank of India", "HDFC", new BigDecimal("500000")));

        log.info(() -> "NBI ledger committed entries: " + nbi.committedCount());
        log.info(() -> "HDFC ledger committed entries: " + hdfc.committedCount());
    }
}

// ─── model/LedgerEntry.java ───
class LedgerEntry {
    final String id, fromBank, toBank; final BigDecimal amount; boolean committed = false;
    LedgerEntry(String id, String fromBank, String toBank, BigDecimal amount) {
            this.id = id;
            this.fromBank = fromBank
            this.toBank = toBank
            this.amount = amount;
    }
}

// ─── node/Peer.java (acts as BOTH client and server) ───
class Peer {
    private static final Logger log = Logger.getLogger("P2P");
    private final String name;
    private final P2PNetwork network;
    private final Map<String, LedgerEntry> ledger = new LinkedHashMap<>(); // full local copy
        Peer(String name, P2PNetwork network) { this.name = name;
        this.network = network; }
    String name() { return name; }

    // CLIENT role: propose an entry and seek majority acceptance from peers.
    void propose(LedgerEntry entry) {
        int votes = network.broadcastForVotes(entry, this);
        int total = network.activePeerCount();
        if (votes * 2 > total) {                 // strict majority
            commit(entry);
            network.broadcastCommit(entry);
            log.info(() -> name + " committed " + entry.id + " (" + votes + "/" + total + " votes)");
        } else {
            log.warning(() -> name + " FAILED to commit " + entry.id + " (" + votes + "/" + total + ")");
        }
    }
    // SERVER role: validate a peer's proposal and vote.
    boolean vote(LedgerEntry entry) {
        boolean valid = entry.amount.signum() > 0 && !ledger.containsKey(entry.id);
        log.fine(() -> name + " votes " + (valid ? "YES" : "NO") + " on " + entry.id);
        return valid;
    }
    // SERVER role: apply a committed entry to the local ledger copy.
    void commit(LedgerEntry entry) { entry.committed = true; ledger.put(entry.id, entry); }
    long committedCount() { return ledger.values().stream().filter(e -> e.committed).count(); }
}

// ─── network/P2PNetwork.java (peer discovery + direct broadcast; NO central server) ───
class P2PNetwork {
    private static final Logger log = Logger.getLogger("P2P");
    private final List<Peer> peers = new ArrayList<>();
        void join(Peer p) { peers.add(p);
        log.info(() -> p.name() + " joined the network"); }
        void leave(Peer p) { peers.remove(p);
        log.warning(() -> p.name() + " left the network"); }
    int activePeerCount() { return peers.size(); }

    // Ask every OTHER peer to vote on a proposal (direct peer-to-peer messaging).
    int broadcastForVotes(LedgerEntry entry, Peer proposer) {
        int votes = 1; // proposer votes for its own valid entry
        for (Peer p : peers) {
            if (p != proposer && p.vote(entry)) votes++;
        }
        return votes;
    }
    // Tell every peer to apply the committed entry (replicate to all copies).
    void broadcastCommit(LedgerEntry entry) {
        for (Peer p : peers) p.commit(entry);
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
